        var unsupported=new FLVER2.Mesh();var wide=new FLVER.Vertex();wide.UVs.Add(new(24,1,0));unsupported.Vertices.Add(wide);var unsupportedMaterial=new FLVER2.Material("ray","S_DiffuseX2[Dn]_Add.mtd",0);unsupportedMaterial.Textures.Add(new(){TilingScale=Vector2.One});bool unsupportedRejected=false;try{StaticMapUV.Apply(unsupported,unsupportedMaterial,"DS1R");}catch(InvalidDataException){unsupportedRejected=true;}Check(unsupportedRejected&&wide.UVs[0]==new Vector3(24,1,0)&&unsupportedMaterial.Textures[0].TilingScale==Vector2.One,"Unsupported overflowing shader must reject without partial mutation");
        var invalidMesh=new FLVER2.Mesh();var valid=new FLVER.Vertex();valid.UVs.Add(new(2,3,0));var invalid=new FLVER.Vertex();invalid.UVs.Add(new(33,0,0));invalidMesh.Vertices.AddRange([valid,invalid]);var invalidMaterial=new FLVER2.Material("invalid","M[ARSN].mtd",0);invalidMaterial.Textures.Add(new(){TilingScale=Vector2.One});bool rejected=false;try{StaticMapUV.Apply(invalidMesh,invalidMaterial,"DS1R");}catch(InvalidDataException){rejected=true;}Check(rejected&&valid.UVs[0]==new Vector3(2,3,0)&&invalidMaterial.Textures[0].TilingScale==Vector2.One,"Out-of-budget UV must reject without partial mutation");
        string sourcePath=Path.Combine(args[1],"map/m10_02_00_00/m2310B2A10.flver.dcx"),targetPath=Path.Combine(args[2],"dvdroot_ps4/map/m40_02_00_00/m40_02_00_00_070018.flver.dcx");var originalSource=File.ReadAllBytes(sourcePath);var originalTarget=File.ReadAllBytes(targetPath);var source=SourceFlver.Read(originalSource,"DS1R");var target=FLVER2.Read(originalTarget);var wall=source.Meshes[1];var targetWall=target.Meshes[0];Check(wall.Vertices.Count==9140&&targetWall.Vertices.Count==9140,"Installed corridor topology changed");var originalErrors=wall.Vertices.Zip(targetWall.Vertices).Count(p=>Vector3.Distance(p.First.UVs[0],p.Second.UVs[0])>31);Check(originalErrors>0,"Existing corridor did not reproduce packed UV overflow");
