        var sourceWords=PackedUVs(originalSource,1);var nativeWords=PackedUVs(candidate);for(int i=0;i<wall.Vertices.Count;i++)Check(sourceWords[i].Take(2).SequenceEqual(nativeWords[i].Take(2)),"Actual corridor native/source raw signed-short UV words differ at vertex"+i);
        Check(File.ReadAllBytes(sourcePath).AsSpan().SequenceEqual(originalSource)&&File.ReadAllBytes(targetPath).AsSpan().SequenceEqual(originalTarget)&&File.ReadAllBytes(donorPath).AsSpan().SequenceEqual(donorBytes),"UV tests modified an input asset");Directory.CreateDirectory("out/map-editor/static-map-uv-tests");File.WriteAllText("out/map-editor/static-map-uv-tests/report.json",JsonSerializer.Serialize(new{status="PASS",profile="DS1R",corridorVertices=wall.Vertices.Count,originalOverflowVertices=originalErrors,sourceSHA256=Hash(originalSource),targetSHA256=Hash(originalTarget),candidateSHA256=Hash(candidate),runtimeTilingScaleConsumer="Requires parent native image validation"},new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine("PASS source1024/native2048 UV precision, packed-word/effective-coordinate preservation, native roundtrip of9140 actual corridor vertices, profile isolation and input preservation");
    }
    static short[][] PackedUVs(byte[] b,int meshIndex=0) {
        if(DCX.Is(b))b=DCX.Decompress(b).ToArray();
        int I(int at)=>BinaryPrimitives.ReadInt32LittleEndian(b.AsSpan(at,4));int dummies=I(20),materials=I(24),nodes=I(28),meshes=I(32),buffers=I(36),faces=I(80);int meshAt=128+dummies*64+materials*32+nodes*128,bufferAt=meshAt+meshes*48+faces*32,layoutAt=bufferAt+buffers*32;
        int bufferIndex=I(I(meshAt+meshIndex*48+44)),buffer=bufferAt+bufferIndex*32,layout=I(buffer+4),stride=I(buffer+8),count=I(buffer+12),start=I(12)+I(buffer+28),layoutHeader=layoutAt+layout*16,members=I(layoutHeader),memberAt=I(layoutHeader+12);var uvOffsets=new List<int>();
        for(int i=0;i<members;i++){int member=memberAt+i*20;if(I(member+12)==5){int type=I(member+8);Check(type is 21 or 22,"Unexpected signed-short UV layout");for(int k=0;k<(type==21?2:4);k++)uvOffsets.Add(I(member+4)+k*2);}}Check(uvOffsets.Count>0,"Packed UV field absent");return Enumerable.Range(0,count).Select(v=>uvOffsets.Select(offset=>BinaryPrimitives.ReadInt16LittleEndian(b.AsSpan(start+v*stride+offset,2))).ToArray()).ToArray();
    }
